exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · clamp params                                           ★☆☆ warm-up
//  concepts: defensive defaults · offset math
// ─────────────────────────────────────────────────────────────────────────
//
//  ?pageSize=250000 is a denial-of-service request; ?pageSize=0 means
//  "not sent". Clamp before the numbers reach the query.

using static Bootcamp.Check;

int ClampPageSize(int requested, int fallback, int max)
{
    if (requested <= 0) return fallback;
    return requested > max ? max : requested;
}

int OffsetOf(int page, int pageSize)
{
    var p = page < 1 ? 1 : page;
    return (p - 1) * pageSize;
}

