exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  03 · sort whitelist                                         ★★☆ core
//  concepts: injection-proof sorting · direction prefix
// ─────────────────────────────────────────────────────────────────────────
//
//  ?sort=-name means "name, descending". The field name must NEVER reach
//  the SQL as typed: map it through a whitelist of known columns.

using static Bootcamp.Check;

(string Field, bool Desc) ParseSort(string? requested, string fallback)
{
    if (string.IsNullOrEmpty(requested)) return (fallback, false);
    var desc = requested[0] == '-';
    var field = desc ? requested[1..] : requested;
    return field.Length == 0 ? (fallback, false) : (field, desc);
}

string MapSort(string field, Dictionary<string, string> allowed, string fallbackColumn)
{
    return allowed.TryGetValue(field.ToLowerInvariant(), out var column) ? column : fallbackColumn;
}

