exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · optional filters                                       ★★☆ core
//  concepts: nullable criteria · conjunction
// ─────────────────────────────────────────────────────────────────────────
//
//  GET /products?name=mug&maxPrice=900&active=true — every filter is
//  optional. Absent filters admit everything; present ones all must hold.

using static Bootcamp.Check;

List<(string Name, int PriceCents, bool Active)> Apply(List<(string Name, int PriceCents, bool Active)> items, string? nameContains, int? maxPriceCents, bool? active)
{
    IEnumerable<(string Name, int PriceCents, bool Active)> q = items;
    if (nameContains is not null) q = q.Where(i => i.Name.Contains(nameContains, StringComparison.OrdinalIgnoreCase));
    if (maxPriceCents is int max) q = q.Where(i => i.PriceCents <= max);
    if (active is bool a) q = q.Where(i => i.Active == a);
    return q.ToList();
}

