exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  05 · cursor token                                           ★★★ stretch
//  concepts: opaque cursors · never throw at the edge
// ─────────────────────────────────────────────────────────────────────────
//
//  Keyset pagination hands the client an opaque "after" token. Decoding it
//  is parsing attacker input: junk must mean null, never a 500.

using System.Globalization;
using System.Text;
using static Bootcamp.Check;

string EncodeCursor(long lastId)
{
    return Convert.ToBase64String(Encoding.UTF8.GetBytes(lastId.ToString(CultureInfo.InvariantCulture)));
}

long? DecodeCursor(string? token)
{
    if (string.IsNullOrEmpty(token)) return null;
    string text;
    try
    {
        text = Encoding.UTF8.GetString(Convert.FromBase64String(token));
    }
    catch (FormatException)
    {
        return null;
    }
    return long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var id) ? id : null;
}

