    Eq(PreconditionHolds("\"v3\"", "\"v3\""), true));

Test("a stale If-Match fails", () =>
    Eq(PreconditionHolds("\"v2\"", "\"v3\""), false));

Test("a missing If-Match fails (boundary: lost-update protection is mandatory)", () =>
    Eq(PreconditionHolds(null, "\"v3\""), false));

Test("If-Match: * holds for any existing tag (boundary)", () =>
    Eq(PreconditionHolds("*", "\"v9\""), true));

Test("StatusFor(missing) -> 404", () =>
    Eq(StatusFor(false, false), 404));

Test("StatusFor(exists, precondition failed) -> 412", () =>
    Eq(StatusFor(true, false), 412));

Test("StatusFor(exists, precondition holds) -> 204", () =>
    Eq(StatusFor(true, true), 204));

