exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  07 · idempotent upsert                                      ★★☆ core
//  concepts: PUT semantics · 201 vs 200
// ─────────────────────────────────────────────────────────────────────────
//
//  PUT /items/{id} creates or replaces — and sending the same request
//  twice must leave the store exactly as sending it once did.

using static Bootcamp.Check;

bool Upsert(Dictionary<string, string> store, string id, string body)
{
    var created = !store.ContainsKey(id);
    store[id] = body;
    return created;
}

int StatusForUpsert(bool created)
{
    return created ? 201 : 200;
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a fresh id is created and stored", () =>
{
    var store = new Dictionary<string, string>();
    Eq(Upsert(store, "a", "v1"), true);
    Eq(store, new Dictionary<string, string> { ["a"] = "v1" });
});

Test("an existing id is replaced, Count unchanged", () =>
{
    var store = new Dictionary<string, string> { ["a"] = "v1" };
    Eq(Upsert(store, "a", "v2"), false);
    Eq(store["a"], "v2");
    Eq(store.Count, 1);
});

Test("replaying the same PUT changes nothing (boundary: idempotent)", () =>
{
    var store = new Dictionary<string, string>();
    Upsert(store, "a", "v1");
    Eq(Upsert(store, "a", "v1"), false);
    Eq(store, new Dictionary<string, string> { ["a"] = "v1" });
});

Test("StatusForUpsert(true) -> 201", () =>
    Eq(StatusForUpsert(true), 201));

Test("StatusForUpsert(false) -> 200", () =>
    Eq(StatusForUpsert(false), 200));

Test("two different ids -> Count 2", () =>
{
    var store = new Dictionary<string, string>();
    Upsert(store, "a", "v1");
    Upsert(store, "b", "v1");
    Eq(store.Count, 2);
});

