exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  08 · merge patch                                            ★★★ stretch
//  concepts: RFC 7386 merge patch · null deletes
// ─────────────────────────────────────────────────────────────────────────
//
//  PATCH with merge-patch rules: a key the patch omits is kept, a key set
//  to null is DELETED, anything else is set. The input stays untouched.

using static Bootcamp.Check;

Dictionary<string, string?> Merge(Dictionary<string, string?> current, Dictionary<string, string?> patch)
{
    var result = new Dictionary<string, string?>(current);
    foreach (var (key, value) in patch)
    {
        if (value is null) result.Remove(key);
        else result[key] = value;
    }
    return result;
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("{b: null, c: 3} on {a: 1, b: 2} -> {a: 1, c: 3} (delete + add in one patch)", () =>
    Eq(Merge(new() { ["a"] = "1", ["b"] = "2" }, new() { ["b"] = null, ["c"] = "3" }),
       new Dictionary<string, string?> { ["a"] = "1", ["c"] = "3" }));

Test("an empty patch is a no-op (boundary)", () =>
    Eq(Merge(new() { ["a"] = "1", ["b"] = "2" }, new()), new Dictionary<string, string?> { ["a"] = "1", ["b"] = "2" }));

Test("{a: 1} on {} -> {a: 1}", () =>
    Eq(Merge(new(), new() { ["a"] = "1" }), new Dictionary<string, string?> { ["a"] = "1" }));

Test("nulling an absent key is a no-op (boundary)", () =>
    Eq(Merge(new() { ["a"] = "1" }, new() { ["z"] = null }), new Dictionary<string, string?> { ["a"] = "1" }));

Test("Merge never mutates the current dictionary", () =>
{
    var current = new Dictionary<string, string?> { ["a"] = "1", ["b"] = "2" };
    Merge(current, new() { ["b"] = null, ["c"] = "3" });
    Eq(current.Count, 2);
    Eq(current, new Dictionary<string, string?> { ["a"] = "1", ["b"] = "2" });
});
